from pathlib import Path
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,PageBreak,Table,TableStyle
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib import colors
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
root=Path(__file__).resolve().parents[1]
pdfmetrics.registerFont(TTFont('S','C:/Windows/Fonts/segoeui.ttf'));pdfmetrics.registerFont(TTFont('SB','C:/Windows/Fonts/segoeuib.ttf'))
s=getSampleStyleSheet();s.add(ParagraphStyle(name='B',fontName='S',fontSize=11,leading=17,spaceAfter=12,textColor=colors.HexColor('#17383b')));s.add(ParagraphStyle(name='H',fontName='SB',fontSize=23,leading=29,spaceAfter=18,textColor=colors.HexColor('#17383b')))
story=[]
def p(t,style='B'):story.append(Paragraph(t,s[style]))
def table(rows):
 data=[[Paragraph(a,s['B']),Paragraph(b,s['B'])] for a,b in rows];t=Table(data,colWidths=[365,142]);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),colors.HexColor('#edf2ef')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),10),('TOPPADDING',(0,0),(-1,-1),9),('BOTTOMPADDING',(0,0),(-1,-1),7)]));story.append(t);story.append(Spacer(1,15))
p('Identidade visual digital<br/>a partir da logo existente','H');p('Clínica Odonto Personnallite | Proposta comercial | 12/10/2026')
p('Objetivo: organizar a apresentação da clínica no site, Instagram e materiais de comunicação, mantendo o desenho da logo atual. Não será criada nem substituída a marca. As propostas de logos alternativas apresentadas anteriormente ficam fora desta entrega.')
p('O que será padronizado','H');p('Cores, tipografia de apoio, espaçamentos, aplicação em fundos claros e escuros, foto de perfil, capas dos destaques e modelos de conteúdo. O símbolo e a assinatura atual serão preservados; ajustes de composição para cada formato não representam redesenho.')
p('Duas opções de contratação','H');table([('Opção 1 - Padronização Digital Essencial','R$ 600'),('Opção 2 - Padronização e Aplicações','R$ 1.000')]);p('As opções são alternativas. Valores sugeridos, cobrados uma única vez. Não incluem mensalidade de Instagram, tráfego pago ou o valor da criação do site. O preço remunera a padronização e as peças, sem cobrança por criação de nova logo.')
p('Base visual','H');p('Verde profundo #17383B, marfim #F8F6EF e dourado suave #B59661 como cores de apoio propostas. A cor original da logo será mantida; eventuais versões monocromáticas serão submetidas à aprovação. Tipografia de apoio será definida com conferência de disponibilidade e licença.')
story.append(PageBreak());p('Opção 1<br/>Padronização Digital Essencial','H');table([('Organização de cores e tipografia de apoio','R$ 100'),('Adaptação da logo existente para perfil e fundos','R$ 100'),('Seis capas dos destaques existentes','R$ 100'),('Três modelos estáticos de publicação','R$ 200'),('Guia resumido de aplicação e exportações','R$ 100'),('TOTAL / pagamento único','R$ 600')]);p('Pagamento sugerido: 2 parcelas de R$ 300. Inclui até duas rodadas consolidadas de ajustes.')
p('Entregas','H');p('Foto de perfil; seis capas: Clínica, Equipe, Cuidados, Próteses, Atendimento e Localização; três modelos de post; paleta e orientação tipográfica; guia resumido; arquivos SVG dos elementos vetoriais, PNGs e PDF do guia. Modelos editáveis em formato acordado, com textos preservados quando possível. Não inclui novas categorias de destaques.')
p('Observação sobre arquivos','H');p('O arquivo vetorial atualmente usado no site será a base. Exportar PNG não transforma fotografias em vetores. Se for necessário reconstruir uma assinatura completa a partir de imagem sem fonte original, o trabalho será avaliado antes de ser incluído. Nenhuma nova logo será entregue como substituta.')
story.append(PageBreak());p('Opção 2<br/>Padronização e Aplicações','H');table([('Todas as entregas da opção essencial','R$ 600'),('Manual ampliado de aplicação','R$ 100'),('Três modelos adicionais de post (seis no total)','R$ 100'),('Cartão frente/verso e papel timbrado','R$ 100'),('Simulações de fachada/uniforme e aplicação no site','R$ 100'),('TOTAL / pagamento único','R$ 1.000')]);p('Pagamento sugerido: 2 parcelas de R$ 500. Inclui até duas rodadas consolidadas de ajustes.')
p('Entregas adicionais','H');p('Manual com cores, tipografia, área de proteção, redução e usos incorretos; seis modelos de post no total; cartão e papel timbrado com dados aprovados; simulações ilustrativas de fachada e uniforme; exemplo de aplicação visual no site. Aplicação técnica definitiva no site poderá usar as horas da manutenção contratada; reformulação completa não está incluída.')
p('Produção externa','H');p('Não inclui impressão, fabricação de fachada, compra de uniforme, fotografia, fontes pagas, pesquisa jurídica ou registro de marca no INPI. Simulações não são projetos técnicos para fabricação. Dados profissionais, medidas, acabamento e requisitos gráficos devem ser confirmados antes de produção.')
story.append(PageBreak());p('Etapas, limites e aprovação','H');p('1. Escolher o pacote e confirmar os arquivos da marca atual. 2. Receber dados, referências e materiais. 3. Preparar padronização e peças. 4. Consolidar até duas rodadas de ajustes. 5. Aprovar e receber arquivos finais após quitação.')
p('Prazo estimado: 7 a 10 dias úteis após aprovação, primeira parcela e recebimento completo dos materiais. Prazo definitivo depende de retorno e disponibilidade. Revisões ajustam a direção combinada; mudança integral de escopo exige orçamento.')
p('A clínica valida nome, telefone, endereço, identificação profissional e autorizações de uso. Não serão inventados profissionais, depoimentos ou resultados. Fotografias de demonstração não serão apresentadas como instalações reais.')
p('Sem dupla cobrança','H');p('A proposta anterior de criação do site incluiu R$ 100 para organização inicial de bio, links e capas. Se esse trabalho tiver sido pago e corresponder à mesma entrega contratada aqui, aplicar crédito de R$ 100 neste pacote: essencial R$ 500 ou ampliado R$ 900. Confirmar o crédito no aceite. Os demais serviços do site permanecem separados.')
p('Após quitação, disponibilizar arquivos finais do escopo contratado à clínica. Nenhuma mudança no site ou Instagram será publicada apenas por emitir esta proposta; publicação depende da aprovação da cliente.')
p('Aceite','H');p('Representante: ____________________<br/>Pacote: Essencial / Aplicações<br/>Valor: ____________________<br/>Crédito aplicável: ____________________<br/>Data, vencimentos e aceite: ____________________')
def foot(c,d):
 c.setFont('S',8);c.setFillColor(colors.HexColor('#63776b'));c.drawString(44,28,'ODONTO PERSONNALLITE | LOGO EXISTENTE PRESERVADA | 12/10/2026');c.drawRightString(550,28,str(d.page))
